#!/usr/bin/env node
/**
 * Builds the clean install scripts from the DDL exported from the old PERICOPE_ERM schema
 * (db/install/source/pericope_erm_ddl.tsv: TABLE_NAME <tab> DDL, one table per line).
 *
 *   node db/install/tools/build.mjs            write 02_tables.sql, 03_foreign_keys.sql and 08_finish.sql
 *   node db/install/tools/build.mjs --report   also print each table's columns (JSON)
 * (node db/install/tools/build-all.mjs rebuilds every generated file.)
 *
 * What it changes in the exported DDL:
 *   - drops the "PERICOPE_ERM". prefix, so the scripts work in any schema
 *   - drops storage, tablespace, LOB storage and index physical clauses (ADW manages these)
 *   - identity columns become GENERATED BY DEFAULT ON NULL, so demo rows can carry fixed ids
 *   - moves every foreign key to 03_foreign_keys.sql, so tables can be created in any order
 *   - leaves scratch/test tables out (SCRATCH below)
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const root = join(here, '..')
const SOURCE = join(root, 'source', 'pericope_erm_ddl.tsv')

/** Debug and test tables from the old database. Not created. */
export const SCRATCH = new Set([
  'HTMLDB_PLAN_TABLE',
  'PERICOPE_UC_RESULTS',
  'PERICOPE_UC_TEST',
  'PER_LOOKUP_MASTER_ERR$',
  'PER_LOOKUP_MASTER_ERR$1',
  'TEMP_DEBUG_OUTPUT',
  'TEST',
  'TMP_TEST_RESULTS',
  'T_TEST_RESULTS',
])

/**
 * Foreign keys replaced in 08_finish.sql: the app stores the control library's id
 * (ERM_MST_CONTROL, created by migration V3) in these columns, not a PER_MST_CONTROL_REGISTER id.
 */
export const REPLACED_FKS = new Set(['PTCI_CTRL_FK', 'PTRM_CTRL_FK'])

/** Index of the parenthesis that closes the one at `open`, skipping quoted text. */
function matchParen(s, open) {
  let depth = 0
  for (let i = open; i < s.length; i++) {
    const c = s[i]
    if (c === "'") {
      i++
      while (i < s.length && !(s[i] === "'" && s[i + 1] !== "'")) i += s[i] === "'" ? 2 : 1
    } else if (c === '"') {
      i = s.indexOf('"', i + 1)
    } else if (c === '(') depth++
    else if (c === ')' && --depth === 0) return i
  }
  throw new Error('unbalanced parentheses')
}

/** Split on commas that are not inside parentheses or quotes. */
function splitTopLevel(s) {
  const parts = []
  let depth = 0
  let start = 0
  for (let i = 0; i < s.length; i++) {
    const c = s[i]
    if (c === "'") {
      i++
      while (i < s.length && !(s[i] === "'" && s[i + 1] !== "'")) i += s[i] === "'" ? 2 : 1
    } else if (c === '"') i = s.indexOf('"', i + 1)
    else if (c === '(') depth++
    else if (c === ')') depth--
    else if (c === ',' && depth === 0) {
      parts.push(s.slice(start, i).trim())
      start = i + 1
    }
  }
  parts.push(s.slice(start).trim())
  return parts.filter(Boolean)
}

function cleanItem(item) {
  return item
    .replace(/\s+COLLATE "[A-Z_]+"/g, '')
    .replace(/GENERATED (ALWAYS|BY DEFAULT( ON NULL)?) AS IDENTITY( MINVALUE| MAXVALUE| INCREMENT BY| START WITH| CACHE| NOCACHE| NOORDER| ORDER| NOCYCLE| CYCLE| NOKEEP| KEEP| NOSCALE| SCALE| NOEXTEND| EXTEND|\s+\d+)*/g, 'GENERATED BY DEFAULT ON NULL AS IDENTITY')
    .replace(/\s+USING INDEX\b.*?(?=\s+(ENABLE|DISABLE)\b|$)/g, '')
    .replace(/\s+VIRTUAL\s*$/, ' VIRTUAL')
    .replace(/\s+/g, ' ')
    .trim()
}

/** The table's ANNOTATIONS(...) clause, if any, from the text after the column list. */
function annotations(tail) {
  const at = tail.search(/\bANNOTATIONS\s*\(/)
  if (at < 0) return ''
  const open = tail.indexOf('(', at)
  return tail.slice(at, matchParen(tail, open) + 1)
}

export function parse() {
  const tables = []
  for (const line of readFileSync(SOURCE, 'utf8').split('\n')) {
    const m = /^([A-Z0-9_$]+)\t(CREATE .*)$/.exec(line)
    if (!m) continue
    const [, name, raw] = m
    const ddl = raw.replace(/"PERICOPE_ERM"\./g, '')
    const head = /^CREATE (GLOBAL TEMPORARY )?TABLE "([A-Z0-9_$]+)"\s*/.exec(ddl)
    if (!head || head[2] !== name) throw new Error(`cannot read DDL for ${name}`)
    const open = ddl.indexOf('(', head[0].length - 1)
    const close = matchParen(ddl, open)
    const tail = ddl.slice(close + 1)
    const items = splitTopLevel(ddl.slice(open + 1, close)).map(cleanItem)
    const fks = items.filter(i => /^(CONSTRAINT "[A-Z0-9_$]+" )?FOREIGN KEY/.test(i))
    const body = items.filter(i => !fks.includes(i))
    const columns = body
      .filter(i => i.startsWith('"'))
      .map(i => {
        const c = /^"([A-Z0-9_$#]+)" (.*)$/.exec(i)
        return { name: c[1], spec: c[2] }
      })
    tables.push({
      name,
      temporary: !!head[1],
      onCommit: (/ON COMMIT (PRESERVE|DELETE) ROWS/.exec(tail) ?? [''])[0],
      annotations: annotations(tail),
      body,
      fks,
      columns,
    })
  }
  return tables
}

const banner = (title, lines) =>
  [
    '-- =============================================================================',
    `-- ${title}`,
    ...lines.map(l => `-- ${l}`.trimEnd()),
    '-- Generated by db/install/tools/build.mjs from db/install/source/pericope_erm_ddl.tsv.',
    '-- Do not edit by hand: change the generator or the source and rebuild.',
    '-- =============================================================================',
    '',
  ].join('\n')

export function buildSchema() {
  const all = parse()
  const tables = all.filter(t => !SCRATCH.has(t.name))
  const names = new Set(tables.map(t => t.name))

  const create = tables.map(t => {
    const kind = t.temporary ? 'CREATE GLOBAL TEMPORARY TABLE' : 'CREATE TABLE'
    const extra = [t.onCommit, t.annotations].filter(Boolean).join('\n')
    return `${kind} "${t.name}" (\n  ${t.body.join(',\n  ')}\n)${extra ? '\n' + extra : ''};\n`
  })
  writeFileSync(
    join(root, '02_tables.sql'),
    banner(`02  Tables (${tables.length}) from the PERICOPE_ERM export, without foreign keys`, [
      'Run after 01_drop_all.sql, in the schema the app will use (PERICOPE_ERM). Foreign keys come in 03.',
      `Left out (scratch/test tables of the old database): ${[...SCRATCH].join(', ')}.`,
    ]) +
      '\n' +
      create.join('\n'),
  )

  const fkLines = []
  const skipped = []
  // A foreign-key column that defaults to 0 would make every insert that leaves it out fail
  // (there is no parent row 0). Such columns default to NULL ("no parent") instead.
  const zeroDefaults = []
  for (const t of tables) {
    for (const fk of t.fks) {
      for (const col of /FOREIGN KEY\s*\(([^)]*)\)/.exec(fk)[1].match(/[A-Z0-9_$#]+/g)) {
        const c = t.columns.find(x => x.name === col)
        if (c && /DEFAULT 0\b/.test(c.spec)) zeroDefaults.push(`  fix_default('${t.name}', '${col}');`)
      }
    }
  }
  for (const t of tables) {
    for (const fk of t.fks) {
      const cname = (/^CONSTRAINT "([A-Z0-9_$]+)"/.exec(fk) ?? [])[1]
      const target = /REFERENCES "([A-Z0-9_$]+)"/.exec(fk)[1]
      if (cname && REPLACED_FKS.has(cname)) {
        skipped.push(`${cname} on ${t.name} (re-pointed to ERM_MST_CONTROL in 08_finish.sql)`)
        continue
      }
      if (!names.has(target)) {
        skipped.push(`${cname ?? 'unnamed'} on ${t.name} (references ${target}, which is not created)`)
        continue
      }
      fkLines.push(`  add('${t.name}', q'[${fk}]');`)
    }
  }
  writeFileSync(
    join(root, '03_foreign_keys.sql'),
    banner(`03  Foreign keys (${fkLines.length})`, [
      'Added after every table exists. Safe to re-run: keys that already exist are skipped.',
      'Foreign-key columns that defaulted to 0 are changed to default to NULL first (0 is not a valid parent).',
      'Any other failure is printed (Database Actions: the Script Output / DBMS Output pane).',
      ...(skipped.length ? ['Not added here:', ...skipped.map(s => `  ${s}`)] : []),
    ]) +
      `
SET SERVEROUTPUT ON
DECLARE
  n_ok   PLS_INTEGER := 0;
  n_fail PLS_INTEGER := 0;
  PROCEDURE fix_default(p_table VARCHAR2, p_column VARCHAR2) IS
  BEGIN
    EXECUTE IMMEDIATE 'ALTER TABLE "' || p_table || '" MODIFY ("' || p_column || '" DEFAULT NULL)';
  END;
  PROCEDURE add(p_table VARCHAR2, p_clause VARCHAR2) IS
  BEGIN
    EXECUTE IMMEDIATE 'ALTER TABLE "' || p_table || '" ADD ' || p_clause;
    n_ok := n_ok + 1;
  EXCEPTION
    WHEN OTHERS THEN
      -- ORA-02275: such a referential constraint already exists; ORA-02264: name already used
      IF SQLCODE NOT IN (-2275, -2264) THEN
        n_fail := n_fail + 1;
        DBMS_OUTPUT.PUT_LINE('FK on ' || p_table || ' failed: ' || SQLERRM);
      END IF;
  END;
BEGIN
  -- Foreign-key columns that defaulted to 0 (no such parent) now default to NULL.
${[...new Set(zeroDefaults)].join('\n')}
${fkLines.join('\n')}
  DBMS_OUTPUT.PUT_LINE('Foreign keys added: ' || n_ok || ', failed: ' || n_fail);
END;
/
`,
  )

  // 08: everything the API reads or writes through ORDS (its table registry, plus the audit-log
  // mirror and settings table it uses directly).
  const registry = readFileSync(join(root, '..', '..', 'api', 'src', 'tables', 'registry.ts'), 'utf8')
  const restObjects = new Set(['ERM_TRN_AUDIT_LOG', 'ERM_MST_APP_SETTING'])
  for (const m of registry.matchAll(/^ {2}([a-z0-9_]+): \{/gm)) restObjects.add(m[1].toUpperCase())
  for (const m of registry.matchAll(/upstreamCandidates: \[([^\]]*)\]/g)) for (const n of m[1].match(/[a-z0-9_]+/g)) restObjects.add(n.toUpperCase())
  const restList = [...restObjects].sort().map(n => `'${n}'`)
  const restIn = restList.reduce((lines, n) => {
    const last = lines[lines.length - 1]
    if (last && last.length + n.length < 96) lines[lines.length - 1] = `${last}, ${n}`
    else lines.push(n)
    return lines
  }, [])
  writeFileSync(
    join(root, '08_finish.sql'),
    banner('08  Finish: control-library keys, REST endpoints, OAuth client for the API', [
      'Run last, after 07_mock_data.sql. Safe to re-run.',
      '1. Applied controls and monitoring items point at the control library (ERM_MST_CONTROL),',
      '   which is what the app stores there (the old keys pointed at PER_MST_CONTROL_REGISTER).',
      `2. REST-enables, with authentication required, the ${restList.length} tables/views the API uses`,
      '   (names that do not exist in this schema are skipped).',
      '3. Creates the OAuth client "pericope-api" (client credentials) and lets it read and write',
      '   those endpoints. The last statement shows its client id and secret for api/.env.',
    ]) +
      `
SET SERVEROUTPUT ON
BEGIN
  pericope_ddl.add_fk('PER_TRN_CONTROL_IMPLEMENTATION', 'FK_PCI_CONTROL', 'CONTROL_ID',    'ERM_MST_CONTROL', 'UUID');
  pericope_ddl.add_fk('PER_TRN_RISK_MONITORING',        'FK_PRM_CONTROL', 'CONTROLS_UUID', 'ERM_MST_CONTROL', 'UUID', 'SET NULL');
  pericope_ddl.create_index('IX_PCI_CONTROL', 'PER_TRN_CONTROL_IMPLEMENTATION', 'CONTROL_ID');
  pericope_ddl.create_index('IX_PRM_CONTROL', 'PER_TRN_RISK_MONITORING', 'CONTROLS_UUID');
END;
/

BEGIN
  FOR o IN (SELECT object_name, object_type FROM user_objects
             WHERE object_type IN ('TABLE', 'VIEW')
               AND object_name IN (
                 ${restIn.join(',\n                 ')})
             ORDER BY object_name) LOOP
    pericope_ddl.enable_rest(o.object_name, o.object_type);
  END LOOP;
  COMMIT;
END;
/

DECLARE
  v_schema VARCHAR2(128) := SYS_CONTEXT('USERENV', 'CURRENT_SCHEMA');
  n        NUMBER;
  PROCEDURE grant_role(p_role VARCHAR2) IS
  BEGIN
    EXECUTE IMMEDIATE q'[BEGIN OAUTH.GRANT_CLIENT_ROLE(p_client_name => 'pericope-api', p_role_name => :r); END;]' USING p_role;
  EXCEPTION
    WHEN OTHERS THEN NULL; -- already granted, or the role does not exist for this object
  END;
BEGIN
  EXECUTE IMMEDIATE q'[SELECT COUNT(*) FROM user_ords_clients WHERE name = 'pericope-api']' INTO n;
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[BEGIN
      OAUTH.CREATE_CLIENT(
        p_name            => 'pericope-api',
        p_grant_type      => 'client_credentials',
        p_owner           => 'Pericope',
        p_description     => 'Pericope API (server to server)',
        p_support_email   => 'admin@example.com',
        p_privilege_names => NULL);
    END;]';
    DBMS_OUTPUT.PUT_LINE('Created OAuth client pericope-api');
  END IF;
  -- The schema-wide AutoREST role, and each object's own role (ORDS creates both).
  grant_role('oracle.dbtools.role.autorest.' || v_schema);
  FOR o IN (SELECT object_name FROM user_objects
             WHERE object_type IN ('TABLE', 'VIEW')
               AND object_name IN (
                 ${restIn.join(',\n                 ')})) LOOP
    grant_role('oracle.dbtools.role.autorest.' || v_schema || '.' || o.object_name);
  END LOOP;
  COMMIT;
  DBMS_OUTPUT.PUT_LINE('OAuth client pericope-api can use the REST endpoints of ' || v_schema);
EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('OAuth client not set up automatically (' || SQLERRM || ').');
    DBMS_OUTPUT.PUT_LINE('Create it in Database Actions > REST > Security > OAuth Clients instead (see db/install/README.md).');
END;
/

-- Copy these into api/.env as ORDS_CLIENT_ID and ORDS_CLIENT_SECRET. Do not paste them anywhere else.
SELECT client_id, client_secret FROM user_ords_clients WHERE name = 'pericope-api';
`,
  )

  console.log(`tables: ${tables.length} (left out ${all.length - tables.length}), foreign keys: ${fkLines.length}, skipped: ${skipped.length}, REST objects: ${restList.length}`)
  if (process.argv.includes('--report')) {
    const out = Object.fromEntries(tables.map(t => [t.name, t.columns.map(c => `${c.name} ${c.spec}`)]))
    writeFileSync(process.argv[process.argv.indexOf('--report') + 1] ?? '/dev/stdout', JSON.stringify(out, null, 1))
  }
}

if (process.argv[1] === fileURLToPath(import.meta.url)) buildSchema()
